impl<T: gx::Real, O: gx::Orientation> Twist<(), T, O> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[0].mul_add(x[0], t1);
        let t4 = x[2].mul_add(x[2], t3);
        t4
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (41 mul, 18 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Twist<(), T, O> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t5 = t0 * t2;
        let t6 = t1 * t1;
        let t9 = t0.mul_add(t0, t6);
        let t10 = t2.mul_add(t2, t9);
        let t11 = t0.mul_add(t1, t5);
        let t12 = t1.mul_add(t2, t11);
        let t14 = t12.mul_add(T::from_i64(2), t10);
        let t15 = t14.recip();
        let t16 = t0 * t15;
        let t17 = t1 * t15;
        let t19 = t16 + t17;
        let t20 = t2.mul_add(t15, t19);
        let t21 = t16 - t17;
        let t22 = x[2] * t15;
        let t23 = x[0] * t15;
        let t24 = x[2] * t22;
        let t25 = x[0] * x[5];
        let t26 = x[1] * x[4];
        let t27 = x[1] * x[5];
        let t28 = x[0] * t20;
        let t29 = x[1] * t20;
        let t30 = x[2] * t20;
        let t32 = t22 * t25;
        let t34 = x[3] * t21;
        let t35 = x[1] * x[3];
        let t37 = t22 * t27;
        let t39 = x[4] * t21;
        let t41 = x[0] * x[3];
        let t43 = x[1] * t15;
        let t45 = t22 * t26;
        let t46 = x[5] * t24;
        let t47 = -t28;
        let t48 = -t29;
        let t49 = -t30;
        let t50 = (-x[3]).mul_add(t24, t34);
        let t51 = t23.mul_add(t26, t32);
        let t53 = t51.mul_add(T::from_i64(2), t50);
        let t54 = x[4].mul_add(t24, t39);
        let t55 = t23.mul_add(t35, t37);
        let t57 = t55.mul_add(T::from_i64(2), -t54);
        let t58 = (-t23).mul_add(t25, t46);
        let t59 = (-t27).mul_add(t43, t58);
        let t60 = t22.mul_add(t41, t45);
        let t62 = t60.mul_add(T::from_i64(2), t59);
        Twist::from_coeffs([t47, t48, t49, t53, t57, t62])
    }

    /// [`inverse`](Self::inverse), or `None` where `x` has no inverse to working precision:
    /// where `x ~x`, the Study number `N` the inverse divides by, is zero next to `x`
    /// (`|N| â¤ n Îµ âxâÂ²`, with `|N|Â²` and `âxâÂ²` the sums of the squared coefficients of `N`
    /// and `x`, and `n = 6` the number of `x`'s), or its norm `d = N conj(N)` is lost to
    /// cancellation (`|d| â¤ n Îµ |N|Â²`), in any lane; or where the inverse is not finite.
    #[inline]
    pub fn try_inverse(self) -> Option<Twist<(), T, O>> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t4 = x[4] * x[4];
        let t7 = x[1] * x[4];
        let t11 = t0 * t2;
        let t12 = t1 * t1;
        let t15 = t0 + t1;
        let t16 = t2 + t15;
        let t17 = x[3].mul_add(x[3], t4);
        let t18 = x[5].mul_add(x[5], t16);
        let t19 = t17 + t18;
        let t20 = x[0].mul_add(x[3], t7);
        let t21 = x[2].mul_add(x[5], t20);
        let t22 = t21 * T::from_i64(2);
        let t23 = -t22;
        let t24 = t0.mul_add(t0, t12);
        let t25 = t2.mul_add(t2, t24);
        let t26 = t0.mul_add(t1, t11);
        let t27 = t1.mul_add(t2, t26);
        let t29 = t27.mul_add(T::from_i64(2), t25);
        let (size, d) = (t19, t29);
        let parts = t16 * t16 + t23 * t23;
        let tol = T::from_i64(6) * T::epsilon();
        if T::all_lt(tol * size, parts.sqrt()) && T::all_lt(tol * parts, d.abs()) {
            Some(self.inverse()).filter(gx::Extensor::is_finite)
        } else {
            None
        }
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn unit(self) -> gx::Unit<Self> {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p4 = x[1] * x[4];
        let p6 = x[0].mul_add(x[0], p1);
        let p7 = x[2].mul_add(x[2], p6);
        let p8 = x[0].mul_add(x[3], p4);
        let p9 = x[2].mul_add(x[5], p8);
        let p10 = p9 * T::from_i64(2);
        let p11 = -p10;
        let [s0, s1] = gx::__private::study::rsqrt_nil(p7, p11);
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t4 = x[3] * s0;
        let t6 = x[4] * s0;
        let t8 = x[5] * s0;
        let t9 = (-x[0]).mul_add(s1, t4);
        let t10 = (-x[1]).mul_add(s1, t6);
        let t11 = (-x[2]).mul_add(s1, t8);
        gx::Unit::new_unchecked(Twist::from_coeffs([t0, t1, t2, t9, t10, t11]))
    }

    /// The same, uncertified: `self` scaled so that `x ~x = 1`, as a plain value. [`unit`](Self::unit)
    /// returns it as a [`gx::Unit`], which the cheaper unit kernels take.
    #[inline(always)]
    pub fn normalized(self) -> Self {
        self.unit().into_inner()
    }

}

impl<T: gx::Real> Twist<(), T, gx::Extrinsic> {
    /// The exponential, a unit versor: `exp(B) = C(BÂ²) + S(BÂ²) B` with `BÂ²` a Study number.
    #[inline]
    #[allow(unused_variables)]
    pub fn exp(self) -> gx::Unit<Motor<(), T>> {
        T::vectorize(#[inline(always)] move || {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p4 = x[1] * x[4];
        let p6 = x[0].mul_add(x[0], p1);
        let p7 = x[2].mul_add(x[2], p6);
        let p8 = -p7;
        let p9 = x[0].mul_add(x[3], p4);
        let p10 = x[2].mul_add(x[5], p9);
        let p11 = p10 * T::from_i64(2);
        let [c0, c1, s0, s1] = gx::__private::study::exp_coeffs_rotation(p8, p11);
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t4 = x[3] * s0;
        let t6 = x[4] * s0;
        let t8 = x[5] * s0;
        let t9 = (-x[0]).mul_add(s1, t4);
        let t10 = (-x[1]).mul_add(s1, t6);
        let t11 = (-x[2]).mul_add(s1, t8);
        gx::Unit::new_unchecked(Motor::from_coeffs([c0, t0, t1, t2, t9, t10, t11, c1]))
        })
    }

}

impl<T: gx::Coef, O: gx::Orientation> gx::__private::NewtonStep for Twist<(), T, O> {
    /// `(3 â x ~x) x / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = t0 + t1;
        let t4 = t2 + t3;
        let t5 = t0 - T::from_i64(3);
        let t7 = (-t4).mul_add(T::from_ratio(1, 3), T::from_i64(1));
        let t8 = x[0] * x[3];
        let t9 = x[1] * x[2];
        let t10 = x[0] * t7;
        let t11 = x[1] * t7;
        let t12 = x[2] * t7;
        let t14 = x[0] * x[1];
        let t16 = x[0] * x[2];
        let t17 = x[5] * t16;
        let t19 = x[3] * t2;
        let t21 = x[4] * t1;
        let t22 = x[5] * t9;
        let t24 = x[4] * t5;
        let t27 = x[4] * t9;
        let t28 = x[5] * t2;
        let t29 = x[5] * t5;
        let t30 = t10 * T::from_ratio(3, 2);
        let t31 = t11 * T::from_ratio(3, 2);
        let t32 = t12 * T::from_ratio(3, 2);
        let t33 = x[4].mul_add(t14, t17);
        let t34 = x[3].mul_add(t1, t19);
        let t36 = (-x[0]).mul_add(t8, x[3]);
        let t38 = t36.mul_add(T::from_ratio(3, 2), -t33);
        let t39 = (-t34).mul_add(T::from_ratio(1, 2), t38);
        let t40 = x[1].mul_add(t8, t22);
        let t41 = x[4].mul_add(t2, t24);
        let t44 = t41.mul_add(T::from_ratio(1, 2), t40);
        let t45 = t21.mul_add(T::from_ratio(3, 2), t44);
        let t46 = -t45;
        let t47 = x[2].mul_add(t8, t27);
        let t48 = x[5].mul_add(t1, t29);
        let t51 = t48.mul_add(T::from_ratio(1, 2), t47);
        let t52 = t28.mul_add(T::from_ratio(3, 2), t51);
        let t53 = -t52;
        Twist::from_coeffs([t30, t31, t32, t39, t46, t53])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

