impl<S: gx::Slots, T: gx::Real, O: gx::Orientation> gx::DivBy<T> for Bivector<S, T, O> {
    type Output = Self;
    #[inline(always)]
    fn div_by(self, rhs: T) -> Self {
        let r = rhs.recip();
        Bivector { o: core::marker::PhantomData, c: self.c.map(|x| gx::__private::SlotArr::<S, T>(x).scale(r).0) }
    }
}

