impl<T: gx::Real, O: gx::Orientation> Quadvector<(), T, O> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[3] * x[4];
        let t4 = x[0].mul_add(x[0], t1);
        let t5 = x[2].mul_add(x[2], t4);
        let t7 = t3.mul_add(T::from_i64(2), t5);
        let t8 = -t7;
        t8
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (26 mul, 12 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Quadvector<(), T, O> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[4];
        let t6 = t0 * t2;
        let t8 = t1 * t1;
        let t10 = t1 * t3;
        let t13 = t3 * t3;
        let t14 = t0.mul_add(t0, t8);
        let t15 = t2.mul_add(t2, t14);
        let t16 = t0.mul_add(t1, t6);
        let t17 = t1.mul_add(t2, t16);
        let t19 = t0.mul_add(t3, t10);
        let t20 = t2.mul_add(t3, t13);
        let t21 = t19 + t20;
        let t23 = t17.mul_add(T::from_i64(2), t15);
        let t24 = t21.mul_add(T::from_i64(4), t23);
        let t25 = t24.recip();
        let t27 = t1 * t25;
        let t29 = t3 * t25;
        let t30 = t0.mul_add(t25, t27);
        let t31 = t2.mul_add(t25, t30);
        let t33 = t29.mul_add(T::from_i64(2), t31);
        let t34 = x[0] * t33;
        let t35 = x[1] * t33;
        let t36 = x[2] * t33;
        let t37 = x[3] * t33;
        let t38 = x[4] * t33;
        let t39 = -t34;
        let t40 = -t35;
        let t41 = -t36;
        let t42 = -t37;
        let t43 = -t38;
        Quadvector::from_coeffs([t39, t40, t41, t42, t43])
    }

    /// [`inverse`](Self::inverse), or `None` where `x` has no inverse to working precision:
    /// where `x ~x`, the Study number `N` the inverse divides by, is zero next to `x`
    /// (`|N| â¤ n Îµ âxâÂ²`, with `|N|Â²` and `âxâÂ²` the sums of the squared coefficients of `N`
    /// and `x`, and `n = 5` the number of `x`'s), or its norm `d = N conj(N)` is lost to
    /// cancellation (`|d| â¤ n Îµ |N|Â²`), in any lane; or where the inverse is not finite.
    #[inline]
    pub fn try_inverse(self) -> Option<Quadvector<(), T, O>> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[4];
        let t5 = x[4] * x[4];
        let t8 = t0 * t2;
        let t10 = t1 * t1;
        let t12 = t1 * t3;
        let t15 = t3 * t3;
        let t16 = t0 + t1;
        let t17 = t2 + t16;
        let t18 = x[3].mul_add(x[3], t5);
        let t19 = t17 + t18;
        let t21 = t3.mul_add(T::from_i64(2), t17);
        let t22 = -t21;
        let t23 = t0.mul_add(t0, t10);
        let t24 = t2.mul_add(t2, t23);
        let t25 = t0.mul_add(t1, t8);
        let t26 = t1.mul_add(t2, t25);
        let t28 = t0.mul_add(t3, t12);
        let t29 = t2.mul_add(t3, t15);
        let t30 = t28 + t29;
        let t32 = t26.mul_add(T::from_i64(2), t24);
        let t33 = t30.mul_add(T::from_i64(4), t32);
        let (size, d) = (t19, t33);
        let parts = t22 * t22;
        let tol = T::from_i64(5) * T::epsilon();
        if T::all_lt(tol * size, parts.sqrt()) && T::all_lt(tol * parts, d.abs()) {
            Some(self.inverse()).filter(gx::Extensor::is_finite)
        } else {
            None
        }
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn unit(self) -> gx::Unit<Self> {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p3 = x[3] * x[4];
        let p4 = x[0].mul_add(x[0], p1);
        let p5 = x[2].mul_add(x[2], p4);
        let p7 = p3.mul_add(T::from_i64(2), p5);
        let p8 = -p7;
        let s0 = (p8).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        let t4 = x[4] * s0;
        gx::Unit::new_unchecked(Quadvector::from_coeffs([t0, t1, t2, t3, t4]))
    }

    /// The same, uncertified: `self` scaled so that `x ~x = 1`, as a plain value. [`unit`](Self::unit)
    /// returns it as a [`gx::Unit`], which the cheaper unit kernels take.
    #[inline(always)]
    pub fn normalized(self) -> Self {
        self.unit().into_inner()
    }

}

impl<T: gx::Real> Quadvector<(), T, gx::Extrinsic> {
    /// The exponential, `exp(z + V) = exp(z) (C(VÂ²) + S(VÂ²) V)` with `V` the rest and
    /// `VÂ²` a Study number (`cosh |v| + sinh |v| vÌ` for a vector of positive square, `cos` and
    /// `sin` for a negative one). A `Even`, not a `gx::Unit`: `x ~x` need not be 1.
    #[inline]
    #[allow(unused_variables)]
    pub fn exp(self) -> Even<(), T> {
        T::vectorize(#[inline(always)] move || {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p3 = x[3] * x[4];
        let p4 = x[0].mul_add(x[0], p1);
        let p5 = x[2].mul_add(x[2], p4);
        let p7 = p3.mul_add(T::from_i64(2), p5);
        let p8 = -p7;
        let [c0, c1, s0, s1] = gx::__private::study::exp_coeffs_central(-1, p8, T::from_i64(0), T::from_i64(0), T::from_i64(0));
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        let t4 = x[4] * s0;
        Even::from_coeffs([c0, T::from_i64(0), T::from_i64(0), T::from_i64(0), T::from_i64(0), T::from_i64(0), T::from_i64(0), T::from_i64(0), T::from_i64(0), T::from_i64(0), T::from_i64(0), t0, t1, t2, t3, t4])
        })
    }

}

impl<T: gx::Coef, O: gx::Orientation> gx::__private::NewtonStep for Quadvector<(), T, O> {
    /// `(3 â x ~x) x / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[3] * x[4];
        let t4 = x[0].mul_add(x[0], t1);
        let t5 = x[2].mul_add(x[2], t4);
        let t7 = t3.mul_add(T::from_i64(2), t5);
        let t9 = t7.mul_add(T::from_ratio(1, 3), T::from_i64(1));
        let t10 = x[0] * t9;
        let t11 = x[1] * t9;
        let t12 = x[2] * t9;
        let t13 = x[3] * t9;
        let t14 = x[4] * t9;
        let t15 = t10 * T::from_ratio(3, 2);
        let t16 = t11 * T::from_ratio(3, 2);
        let t17 = t12 * T::from_ratio(3, 2);
        let t18 = t13 * T::from_ratio(3, 2);
        let t19 = t14 * T::from_ratio(3, 2);
        Quadvector::from_coeffs([t15, t16, t17, t18, t19])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

